fonksyon dicothomy(a,b,e) {
  ma7dBa9i (((b-a)/2) > e) {
    9ayed mid = (a+b)/2;
    ilakan (f(mid) == 0) {
      rjje3 mid;
    } sinn {
      ilakan (f(a) * f(mid) < 0) {
        b = mid;
      } sinn {
        a = mid;
      }
    }
  }
  rjje3 (a+b)/2;
}

fonksyon newton(x0, e) {
  9ayed x1 = x0 - (f(x0)/df(x0));
  ma7dBa9i (abs(x1-x0) > e) {
    x0 = x1;
    x1 = x0 - (f(x0)/df(x0));
  }
  rjje3 x1;
}

fonksyon pointFixe(x0, e) {
  9ayed x1 = g(x0);
  ma7dBa9i (abs(x1-x0) > e) {
    x0 = x1;
    x1 = g(x0);
  }
  rjje3 x1;
}

